import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Big picture overview","description":"","frontmatter":{"title":"Big picture overview"},"headers":[],"relativePath":"docs/overview/big-picture-overview.md","filePath":"docs/overview/big-picture-overview.md","lastUpdated":1791494193000}'),n={name:"docs/overview/big-picture-overview.md"};function i(s,e,c,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="big-picture-overview" tabindex="-1">Big picture overview <a class="header-anchor" href="#big-picture-overview" aria-label="Permalink to &quot;Big picture overview&quot;">​</a></h1><p>OrbySystems turns the financial records you already have into a private place to explore your household&#39;s money. Bring at least three consecutive months of statements or exports; six months gives OrbySystems a stronger view of recurring spending, income, and investment patterns. You do not have to recreate that history in forms.</p><h2 id="projects-in-one-picture-out" tabindex="-1">Projects in, one picture out <a class="header-anchor" href="#projects-in-one-picture-out" aria-label="Permalink to &quot;Projects in, one picture out&quot;">​</a></h2><p>Keep each kind of record in its own project:</p><ul><li><strong>Spending &amp; Income</strong> holds bank and credit-card activity.</li><li><strong>Investments</strong> holds brokerage and retirement-account activity.</li></ul><p>A <strong>Combined</strong> workbook brings projects together for a household-wide view. A <strong>Retirement</strong> workbook uses those same source projects for a retirement outlook and, when licensed, deeper planning. The source records stay in their projects, so you can add another account or update a statement without rebuilding the workbook.</p><p>Start with the example household if you want to look around first. It lets you try the dashboards, recipes, and Demo Retirement without using personal data. When the flow makes sense, create projects from your own statements and build your own workbook.</p><h2 id="start-with-a-real-question" tabindex="-1">Start with a real question <a class="header-anchor" href="#start-with-a-real-question" aria-label="Permalink to &quot;Start with a real question&quot;">​</a></h2><p>OrbySystems is designed around questions such as:</p><ul><li><em>Where does our money go each month?</em></li><li><em>What could we change without changing the life we like?</em></li><li><em>What did we actually earn after deposits and withdrawals?</em></li><li><em>Could we take a break, change careers, or retire—and what would have to change?</em></li></ul><p>AI does the analysis. OrbySystems enforces numerical accuracy, keeps key figures connected to your records, and holds back numbers it cannot support with evidence.</p><h2 id="local-by-default-online-when-you-choose" tabindex="-1">Local by default, online when you choose <a class="header-anchor" href="#local-by-default-online-when-you-choose" aria-label="Permalink to &quot;Local by default, online when you choose&quot;">​</a></h2><p>If you already have the statements, OrbySystems can analyze them locally after setup without an Orby account, cloud upload, or network connection. You can leave Wi-Fi on; offline operation is simply another way to confirm that core analysis does not depend on the cloud.</p><p>Online tools and agents are optional. You decide when to use them and what job they may perform, including retrieving statements. An Orby account unlocks services you request, such as paid capabilities or support for new tools and parsers; it does not move your statements or analysis off your laptop.</p><h2 id="current-licensing" tabindex="-1">Current licensing <a class="header-anchor" href="#current-licensing" aria-label="Permalink to &quot;Current licensing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Coverage</th></tr></thead><tbody><tr><td><strong>Free</strong></td><td>Analyze projects and a Combined workbook using any selected six consecutive calendar months. You can choose a different six-month window for another analysis.</td></tr><tr><td><strong>Base</strong></td><td>Unlimited analysis for the statement year you cover.</td></tr><tr><td><strong>Retirement Complete</strong></td><td>Adds the available Retirement Complete planning capabilities and includes Base for the same covered year.</td></tr></tbody></table><p>You can import and keep your source records independently of the analysis window. Current pricing and availability are shown in your Orby account and at checkout. See <a href="/docs/settings/license">License</a> for activation and coverage details.</p><p>Most development is funded by the creators; paid licenses help cover ongoing support and operating costs.</p><p>Ready to begin? <a href="/docs/getting-started/install-orby">Install OrbySystems</a>, then <a href="/docs/getting-started/create-first-project">create your first project</a>.</p>',19)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
